N=<SCRATCH>/next10; cat > $N/crc_proto.c <<'EOF'
/* CRC-SLICE's prototype: zlib's CRC-32 eight bytes a step (slicing-by-8), beside the byte table it replaces. */
#include <stddef.h>
#include <stdint.h>
#include "tables.inc"
uint32_t crc_byte(const uint8_t *d, size_t n);
uint32_t crc_slice8(const uint8_t *d, size_t n);
uint32_t crc_byte(const uint8_t *d, size_t n) {
  uint32_t c = 0xFFFFFFFFu;
  for (size_t i = 0; i < n; i++) c = bcir_crc_slice[0][(c ^ d[i]) & 0xFFu] ^ (c >> 8);
  return c ^ 0xFFFFFFFFu;
}
uint32_t crc_slice8(const uint8_t *d, size_t n) {
  uint32_t c = 0xFFFFFFFFu;
  size_t i = 0;
  for (; i + 8u <= n; i += 8u) {
    uint32_t lo = c ^ ((uint32_t)d[i] | (uint32_t)d[i + 1] << 8 | (uint32_t)d[i + 2] << 16 | (uint32_t)d[i + 3] << 24);
    uint32_t hi = (uint32_t)d[i + 4] | (uint32_t)d[i + 5] << 8 | (uint32_t)d[i + 6] << 16 | (uint32_t)d[i + 7] << 24;
    c = bcir_crc_slice[7][lo & 0xFFu] ^ bcir_crc_slice[6][(lo >> 8) & 0xFFu] ^ bcir_crc_slice[5][(lo >> 16) & 0xFFu] ^
        bcir_crc_slice[4][lo >> 24] ^ bcir_crc_slice[3][hi & 0xFFu] ^ bcir_crc_slice[2][(hi >> 8) & 0xFFu] ^
        bcir_crc_slice[1][(hi >> 16) & 0xFFu] ^ bcir_crc_slice[0][hi >> 24];
  }
  for (; i < n; i++) c = bcir_crc_slice[0][(c ^ d[i]) & 0xFFu] ^ (c >> 8);
  return c ^ 0xFFFFFFFFu;
}
EOF
clang -std=c11 -O2 -Wall -Wextra -Werror -fPIC -shared -I $N $N/crc_proto.c -o $N/libcrc.so && python3 - "$N/libcrc.so" <<'EOF'
import ctypes, random, sys, zlib
lib = ctypes.CDLL(sys.argv[1])
for f in (lib.crc_byte, lib.crc_slice8):
    f.restype = ctypes.c_uint32
    f.argtypes = (ctypes.c_char_p, ctypes.c_size_t)
rng = random.Random(5)
n = 0
for length in list(range(0, 300)) + [1000, 4095, 4096, 4097, 65536 + 3, 609997]:
    for offset in range(4 if length < 300 else 1):
        data = bytes(rng.getrandbits(8) for _ in range(length + offset))
        buf = ctypes.create_string_buffer(data, len(data))
        p = ctypes.cast(ctypes.addressof(buf) + offset, ctypes.c_char_p)
        want = zlib.crc32(data[offset:])
        assert lib.crc_byte(p, length) == want and lib.crc_slice8(p, length) == want, (length, offset)
        n += 1
for fill in (0x00, 0xFF):
    data = bytes([fill]) * 100003
    assert lib.crc_slice8(data, len(data)) == zlib.crc32(data)
print("equal to zlib.crc32 on", n, "buffers + 2 fills")
EOF

N=<SCRATCH>/next10; cat > $N/model_crc.c <<'EOF'
/* NEXT-6: the BCIRQ8 loader's CRC passes on one model -- the bitwise loop bcir_q8_model.c runs (copied: crc_update,
 * 8 dependent steps a byte) over the body and then each tensor, against the byte table (bcir_crc32) and the
 * slicing-by-8 prototype over the same bytes -- and bcir_q8_model_load whole; each the median of ROUNDS rounds.
 * usage: model_crc MODEL.bcirq8 ROUNDS */
#define _POSIX_C_SOURCE 200809L
#include "bcir_q8_model.h"
#include "bcir_runtime.h"
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
uint32_t crc_slice8(const uint8_t *d, size_t n);
static uint32_t crc_update(uint32_t state, const unsigned char *data, size_t size) {
  size_t i;
  int bit;
  for (i = 0; i < size; ++i) {
    state ^= data[i];
    for (bit = 0; bit < 8; ++bit) state = (state >> 1) ^ (0xEDB88320u & (0u - (state & 1u)));
  }
  return state;
}
static double now(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}
static int cmp(const void *a, const void *b) {
  double x = *(const double *)a, y = *(const double *)b;
  return x < y ? -1 : x > y;
}
int main(int argc, char **argv) {
  FILE *f;
  long len;
  unsigned char *p;
  int rounds, r, k;
  double ms[4][101];
  volatile uint32_t sink = 0;
  if (argc != 3 || !(f = fopen(argv[1], "rb"))) return 2;
  rounds = atoi(argv[2]);
  if (rounds < 1 || rounds > 101) return 2;
  fseek(f, 0, SEEK_END);
  len = ftell(f);
  rewind(f);
  p = malloc((size_t)len);
  if (!p || fread(p, 1, (size_t)len, f) != (size_t)len) return 2;
  fclose(f);
  for (r = -1; r < rounds; r++)
    for (k = 0; k < 4; k++) {
      double t0 = now();
      if (k == 0) sink ^= crc_update(0xFFFFFFFFu, p, (size_t)len) ^ 0xFFFFFFFFu;
      else if (k == 1) sink ^= bcir_crc32(p, (size_t)len);
      else if (k == 2) sink ^= crc_slice8(p, (size_t)len);
      else {
        bcir_q8_model m;
        char err[256];
        bcir_q8_model_init(&m);
        if (bcir_q8_model_load(argv[1], &m, err, sizeof err) != 0) {
          fprintf(stderr, "load: %s\n", err);
          return 1;
        }
        bcir_q8_model_free(&m);
      }
      if (r >= 0) ms[k][r] = (now() - t0) * 1e3;
    }
  if (crc_update(0xFFFFFFFFu, p, (size_t)len) != (bcir_crc32(p, (size_t)len) ^ 0xFFFFFFFFu) ||
      crc_slice8(p, (size_t)len) != bcir_crc32(p, (size_t)len))
    return 1;
  for (k = 0; k < 4; k++) qsort(ms[k], (size_t)rounds, sizeof(double), cmp);
  printf("{\"file_octets\":%ld,\"rounds\":%d,\"bitwise_file_ms\":%.4f,\"table_file_ms\":%.4f,\"slice8_file_ms\":%.4f,"
         "\"load_ms\":%.4f,\"sink\":%u}\n",
         len, rounds, ms[0][rounds / 2], ms[1][rounds / 2], ms[2][rounds / 2], ms[3][rounds / 2], (unsigned)sink);
  return 0;
}
EOF
R=<REPO>; clang -std=c11 -O2 -Wall -Wextra -Werror -ffp-contract=off -I $R/runtime/c -I $N $N/model_crc.c $N/crc_proto.c $R/runtime/c/bcir_runtime.c $R/runtime/c/bcir_q8_model.c -o $N/model_crc -lm 2>&1 | head; ls $N/model_crc && echo built

